const defaultFaqs=[['Кто сопровождает группу?','Часть путешествий Гаухар сопровождает лично. Также с группами работают групп-лидеры и местные специалисты. В отдельных программах предусмотрены услуги местных экскурсоводов.'],['Какой формат размещения?','Обычно участники размещаются по два человека в номере. Если вы путешествуете один, мы можем подобрать соседа. Одноместное размещение возможно за дополнительную плату.'],['Можно ли поехать одному?','Конечно. Многие участники присоединяются самостоятельно — групповой формат помогает легко познакомиться с новыми людьми.'],['Как оплатить путешествие?','Можно оплатить полностью либо несколькими платежами по согласованному графику. Все условия и окончательная сумма фиксируются до оплаты.'],['Нужно ли самостоятельно оформлять визу?','Мы предоставляем список документов и сопровождаем процесс оформления визы в рамках выбранного пакета. Решение о выдаче принимает консульство.'],['Что делать, если я не смогу поехать?','Условия отмены зависят от даты отказа и уже оплаченных услуг. Подробные правила указываются в договоре до бронирования.']];
const defaultTours=[
 {id:'korea-japan',title:'Корея + Япония',route:'Сеул — Пусан — Осака — Киото — Нара — Токио',dates:'20–29 марта 2027',days:'10 дней',price:'от $2 850',places:'6 мест',status:'Открыт набор',image:'/assets/media/tour-korea-japan.jpg'},
 {id:'japan-korea',title:'Япония + Корея',route:'Токио — Киото — Осака — Нара — Пусан — Сеул',dates:'12–21 апреля 2027',days:'10 дней',price:'от $2 950',places:'3 места',status:'Осталось несколько мест',image:'/assets/media/tour-japan-korea.jpg'},
 {id:'other-japan',title:'Другая Япония',route:'Канадзава — Такаяма — Коясан — Наосима',dates:'8–20 мая 2027',days:'13 дней',price:'от $3 650',places:'Скоро',status:'Скоро анонс',image:'/assets/media/tour-other-japan.jpg'},
 {id:'private-asia',title:'Ваша Азия',route:'Маршрут создаём вместе',dates:'В удобные даты',days:'от 7 дней',price:'по запросу',places:'Индивидуально',status:'Принимаем заявки',image:'/assets/media/tour-private-asia.jpg'}
];
const sectionNames={hero:'Первый экран',intro:'Вступление',proof:'Цифры и доверие',trips:'Форматы и туры',manifesto:'Наш подход',calendar:'Календарь',about:'О проекте','visa-support':'Визовая поддержка',gallery:'Галерея',faq:'Вопросы и ответы',contact:'Форма заявки'};
const defaultOrder=Object.keys(sectionNames);let order=[],uploadValues={},mediaUploads={},activeConfig={};
async function loadConfig(){const {data,error}=await db.from('site_config').select('*').eq('id','main').single();if(error)throw error;activeConfig={content:data.content||{},media:data.media||{},tours:data.tours||[],faqs:data.faqs||[],sectionOrder:data.section_order||[]}}
async function showDashboard(){document.querySelector('#login-panel').hidden=true;document.querySelector('#dashboard').hidden=false;try{await loadConfig();renderEditor()}catch(error){document.querySelector('#save-status').textContent=`Ошибка загрузки: ${error.message}`}}
(async()=>{const {data}=await db.auth.getSession();if(data.session)showDashboard()})();
document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const errorEl=document.querySelector('#login-error');errorEl.textContent='Входим…';const {error}=await db.auth.signInWithPassword({email:document.querySelector('#email').value.trim(),password:document.querySelector('#password').value});if(error){errorEl.textContent='Неверный email или пароль';return}errorEl.textContent='';showDashboard()};
document.querySelector('#logout').onclick=async()=>{await db.auth.signOut();location.reload()};
document.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(el=>el.classList.remove('active'));btn.classList.add('active');document.querySelector(`[data-panel="${btn.dataset.tab}"]`).classList.add('active')});
const escapeAttr=value=>String(value||'').replaceAll('&','&amp;').replaceAll('"','&quot;');
function renderEditor(){const saved=activeConfig,content={...defaultContent,...saved.content},media={...defaultMedia,...saved.media};document.querySelector('#content-fields').innerHTML=Object.entries(contentGroups).map(([group,keys])=>`<div class="field wide"><span>${group}</span></div>${keys.map(key=>`<label class="field ${(key.endsWith('Copy')||key==='aboutTeam')?'wide':''}"><span>${contentLabels[key]}</span><textarea name="content.${key}" rows="${(key.endsWith('Copy')||key==='aboutTeam')?4:2}">${content[key]}</textarea></label>`).join('')}`).join('');renderFaqs(saved.faqs?.length?saved.faqs:defaultFaqs);renderMedia(media);const tours=defaultTours.map(t=>({...t,...(saved.tours||[]).find(x=>x.id===t.id)}));document.querySelector('#tour-fields').innerHTML=tours.map((t,i)=>`<article class="tour-editor" data-tour="${t.id}"><div class="tour-preview" style="background-image:url('${t.image}')"></div><div><h3>${t.title}</h3><div class="tour-inputs">${['title','route','dates','days','price','places','status','image'].map(key=>`<label class="field ${key==='route'||key==='image'?'wide':''}"><span>${({title:'Название',route:'Маршрут',dates:'Даты',days:'Длительность',price:'Цена',places:'Места',status:'Статус',image:'URL фотографии'})[key]}</span><input name="tour.${i}.${key}" value="${escapeAttr(t[key])}"></label>`).join('')}<label class="field wide"><span>Загрузить фотографию</span><input class="upload" type="file" accept="image/jpeg,image/png,image/webp" data-tour-upload="${t.id}"></label><input type="hidden" name="tour.${i}.id" value="${t.id}"></div></div></article>`).join('');document.querySelectorAll('[data-tour-upload]').forEach(input=>input.onchange=()=>readUpload(input,'tour'));order=Array.isArray(saved.sectionOrder)&&saved.sectionOrder.length?[...saved.sectionOrder.filter(x=>sectionNames[x]),...defaultOrder.filter(x=>!saved.sectionOrder.includes(x))]:[...defaultOrder];renderOrder()}
function renderFaqs(faqs){document.querySelector('#faq-fields').innerHTML=`<div class="field wide"><span>Вопросы и ответы FAQ</span></div>`+faqs.map(([q,a],i)=>`<article class="faq-editor"><h3>Вопрос ${i+1}</h3><label class="field"><span>Вопрос</span><textarea name="faq.${i}.q" rows="3">${q}</textarea></label><label class="field"><span>Ответ</span><textarea name="faq.${i}.a" rows="4">${a}</textarea></label></article>`).join('')}
function renderMedia(media){document.querySelector('#media-fields').innerHTML=Object.entries(defaultMedia).map(([key])=>{const video=key==='heroVideo',value=media[key];return `<article class="media-editor"><div class="media-preview" ${video?'':`style="background-image:url('${value}')"`}>${video?`<video src="${value}" muted loop playsinline controls></video>`:''}</div><h3>${mediaLabels[key]}</h3><label class="field"><span>URL файла</span><input name="media.${key}" value="${escapeAttr(value)}"></label><label class="field"><span>Загрузить файл</span><input class="upload" type="file" accept="${video?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'}" data-media-upload="${key}"></label><p class="media-note">${video?'MP4/WebM, до 10 МБ':'JPG/PNG/WebP, до 5 МБ'}</p></article>`}).join('');document.querySelectorAll('[data-media-upload]').forEach(input=>input.onchange=()=>readUpload(input,'media'))}
function readUpload(input,type){const file=input.files[0];if(!file)return;const max=type==='media'&&input.dataset.mediaUpload==='heroVideo'?10000000:5000000;if(file.size>max){alert(`Файл слишком большой. Максимум ${max===10000000?'10 МБ':'5 МБ'}.`);input.value='';return}const key=type==='tour'?input.dataset.tourUpload:input.dataset.mediaUpload,url=URL.createObjectURL(file);if(type==='tour'){uploadValues[key]=file;input.closest('.tour-editor').querySelector('.tour-preview').style.backgroundImage=`url('${url}')`}else{mediaUploads[key]=file;const preview=input.closest('.media-editor').querySelector('.media-preview');if(key==='heroVideo')preview.innerHTML=`<video src="${url}" muted loop playsinline controls></video>`;else preview.style.backgroundImage=`url('${url}')`}}
async function uploadFile(file,prefix){const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]+/g,'-'),path=`${prefix}/${Date.now()}-${safe}`;const {error}=await db.storage.from('site-media').upload(path,file,{cacheControl:'31536000'});if(error)throw error;return db.storage.from('site-media').getPublicUrl(path).data.publicUrl}
function renderOrder(){document.querySelector('#section-order').innerHTML=order.map((key,i)=>`<li><span>${String(i+1).padStart(2,'0')} · ${sectionNames[key]}</span><div class="order-actions"><button type="button" data-move="up" data-key="${key}" aria-label="Выше"><span class="chevron up"></span></button><button type="button" data-move="down" data-key="${key}" aria-label="Ниже"><span class="chevron down"></span></button></div></li>`).join('');document.querySelectorAll('[data-move]').forEach(btn=>btn.onclick=()=>move(btn.dataset.key,btn.dataset.move))}
function move(key,direction){const i=order.indexOf(key),to=direction==='up'?i-1:i+1;if(to<0||to>=order.length)return;[order[i],order[to]]=[order[to],order[i]];renderOrder()}
document.querySelector('#editor-form').onsubmit=async e=>{e.preventDefault();const status=document.querySelector('#save-status');status.textContent='Сохраняем…';const fd=new FormData(e.target),content={},media={},faqs=defaultFaqs.map((_,i)=>[fd.get(`faq.${i}.q`)||'',fd.get(`faq.${i}.a`)||'']),tours=defaultTours.map((base,i)=>{const item={id:base.id};['title','route','dates','days','price','places','status','image'].forEach(key=>item[key]=fd.get(`tour.${i}.${key}`)||'');return item});Object.keys(defaultContent).forEach(key=>content[key]=fd.get(`content.${key}`)||'');Object.keys(defaultMedia).forEach(key=>media[key]=fd.get(`media.${key}`)||defaultMedia[key]);try{for(const [key,file]of Object.entries(mediaUploads))media[key]=await uploadFile(file,`media/${key}`);for(const [id,file]of Object.entries(uploadValues)){const tour=tours.find(x=>x.id===id);tour.image=await uploadFile(file,`tours/${id}`)}const {data:{user}}=await db.auth.getUser();const {error}=await db.from('site_config').upsert({id:'main',content,media,faqs,tours,section_order:order,updated_at:new Date().toISOString(),updated_by:user.id});if(error)throw error;activeConfig={content,media,faqs,tours,sectionOrder:order};uploadValues={};mediaUploads={};status.textContent='Опубликовано для всех посетителей.';setTimeout(()=>status.textContent='',5000)}catch(error){status.textContent=`Ошибка: ${error.message}`}};
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset-site').onclick=()=>dialog.showModal();document.querySelector('#cancel-reset').onclick=()=>dialog.close();document.querySelector('#confirm-reset').onclick=async()=>{const {data:{user}}=await db.auth.getUser();const {error}=await db.from('site_config').upsert({id:'main',content:{},media:{},faqs:[],tours:[],section_order:[],updated_at:new Date().toISOString(),updated_by:user.id});if(error){alert(error.message);return}activeConfig={};uploadValues={};mediaUploads={};dialog.close();renderEditor();document.querySelector('#save-status').textContent='Исходная версия опубликована.'};
